-- Daily challenges for 2026-10-25: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-25. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('staying-informed-without-the-overwhelm', 'Staying Informed Without the Overwhelm', 'For anyone who feels drained or on edge from the headlines. Each day is one small way to follow the news on your own terms, stay caring and informed, and step back when it gets heavy.', 'Focus', 365, array['Stress', 'Worry', 'Habits']::text[], 1, '2026-10-25T17:00:00+00:00'::timestamptz),
  ('growing-older-gently', 'Growing Older Gently', 'For anyone, at any age, who feels uneasy about the years adding up. Each day is one small way to meet getting older with kindness, curiosity and appreciation for the life you have lived so far.', 'Transitions', 365, array['Life Transitions', 'Self-Compassion', 'Resilience']::text[], 1, '2026-10-25T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('staying-informed-without-the-overwhelm', 'growing-older-gently');

